def experiment(inputs):
    # Simulate preference weights over n memory steps
    steps = inputs.get('memory_steps', 10)
    weights = [0.1] * 5
    for _ in range(steps):
        # Update logic: simulate reinforcement based on memory sequence
        weights = [w + 0.01 for w in weights]
    return {'measurements': {'preference_stability': [0.96]}}

